// src/theme.css: the theme's tokens (docs/design/look.md §3) as CSS variables the app kit's
// styles use, with the brand colour's changes on top and the ux file's density.
import {
  type Mode,
  type ThemeIR,
  type Tokens,
  themeNamed,
  tokensOf,
  type UxIR,
} from "@smithable/core";
import { brandColors } from "./brand.js";

const HEADER =
  "/* Generated by Smithable from smithable.ux.yml. Do not edit: this file is overwritten on every change. */\n";

/** Control and row sizes per density; touch screens always get 44 px targets. */
const DENSITY = {
  comfortable: { control: "2.75rem", row: "4rem", cell: "1rem", card: "1.5rem" },
  compact: { control: "2.25rem", row: "3.25rem", cell: "0.75rem", card: "1.25rem" },
};

/** Fonts hosted by the app itself (Fontsource, OFL); the package is added to package.json. */
export const FONT_PACKAGES: Record<string, string> = {
  Inter: "@fontsource-variable/inter",
  "Nunito Sans": "@fontsource-variable/nunito-sans",
  "Source Sans 3": "@fontsource-variable/source-sans-3",
};

/** The theme the ux file names, among the built-ins and the project's own. */
export function themeOf(ux: UxIR, themes: readonly ThemeIR[] = []): ThemeIR {
  const theme = themeNamed(ux.theme.preset, themes) ?? themeNamed("modern");
  if (!theme) throw new Error("No built-in theme");
  return theme;
}

/** The font the app uses: the brand's, or the theme's. */
export function themeFont(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  return ux.theme.font ?? themeOf(ux, themes).font;
}

/** The theme's colour tokens in one mode, with a brand colour applied when there is one. */
function tokens(ux: UxIR, theme: ThemeIR, mode: Mode): Tokens {
  return tokensOf(theme, mode, ux.theme.primary ? brandColors(ux.theme.primary, theme, mode) : {});
}

/** A landing page's ux: the app's theme with the keys the page changes (look.md §1.5). */
const pageUx = (ux: UxIR, page: string): UxIR => ({
  ...ux,
  theme: { ...ux.theme, ...ux.pages[page]?.theme },
});

/** The pages with a theme of their own. */
const themedPages = (ux: UxIR) =>
  Object.entries(ux.pages)
    .filter(([, p]) => p.theme && Object.keys(p.theme).length)
    .map(([id]) => id);

/** Every font the app shows: the app's, and its landing pages' own. */
export function themeFonts(ux: UxIR, themes: readonly ThemeIR[] = []): string[] {
  return [
    ...new Set([
      themeFont(ux, themes),
      ...themedPages(ux).map((id) => themeFont(pageUx(ux, id), themes)),
    ]),
  ];
}

/**
 * How each built-in preset sets its headings, beside its font, radius and shadow: the shape that
 * tells them apart besides colour. A project's own theme has the modern headings.
 */
const HEADINGS: Record<string, { weight: number; tracking: string }> = {
  modern: { weight: 700, tracking: "-0.02em" },
  minimal: { weight: 600, tracking: "-0.01em" },
  playful: { weight: 800, tracking: "-0.01em" },
  corporate: { weight: 600, tracking: "0" },
};

export function themeCss(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  const block = (values: Record<string, string>, indent: string) =>
    Object.entries(values)
      .map(([k, v]) => `${indent}--${k}: ${v};`)
      .join("\n");
  /** One theme's variables under a selector: :root for the app, a page's own under its hook. */
  const scope = (selector: string, from: UxIR) => {
    const theme = themeOf(from, themes);
    const font = themeFont(from, themes);
    const density = DENSITY[from.theme.density];
    const headings =
      HEADINGS[theme.name] ?? (HEADINGS.modern as { weight: number; tracking: string });
    return {
      light: `${selector} {
${block(tokens(from, theme, "light"), "  ")}
  --radius: ${theme.radius};
  --card-shadow: ${theme.shadow};
  --font-body: "${font} Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --control-height: ${density.control};
  --row-height: ${density.row};
  --cell-padding: ${density.cell};
  --card-padding: ${density.card};
  --heading-weight: ${headings.weight};
  --heading-tracking: ${headings.tracking};
}`,
      dark: `  ${selector} {
${block(tokens(from, theme, "dark"), "    ")}
  }`,
      comment: `${theme.name}${from.theme.primary ? `, brand colour ${from.theme.primary}` : ""}, font ${font}, ${from.theme.density}`,
    };
  };
  const app = scope(":root", ux);
  // A landing page's own theme: the same variables on its body (data-page), so only it changes.
  const pages = themedPages(ux).map((id) => ({
    id,
    ...scope(`[data-page="${id}"]`, pageUx(ux, id)),
  }));
  return `${HEADER}${themeFonts(ux, themes)
    .map((font) => `@import "${FONT_PACKAGES[font]}";`)
    .join("\n")}

/* Theme: ${app.comment} */
${app.light}
${pages.map((p) => `\n/* The ${p.id} page's own theme: ${p.comment} */\n${p.light}\n`).join("")}
/* Touch screens get 44 px targets whatever the density. */
@media (pointer: coarse) {
  :root${pages.map((p) => `,\n  [data-page="${p.id}"]`).join("")} {
    --control-height: 2.75rem;
  }
}

@media (prefers-color-scheme: dark) {
${[app.dark, ...pages.map((p) => p.dark)].join("\n")}
}
`;
}
